package com.handy.parakeet;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.media.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.Arrays;
public class Main3Activity extends Activity{CheckBox live;TextView s,t;Button b;Spinner mode;EditText cores;volatile boolean rec;Thread th;static String loadError=null;static{try{System.loadLibrary("transcribe");}catch(Throwable e){loadError=e.toString();}}static native String nativeLoadModelOptions(String p,int backend,int threads);static native String nativeBegin(boolean live);static native String nativeText();static native String nativeReplay();static native String nativeStart();static native String nativeFeed(float[]a);static native String nativeFinish();static native void nativeClose();
public void onCreate(Bundle x){super.onCreate(x);if(loadError!=null){TextView error=new TextView(this);error.setPadding(24,48,24,24);error.setTextIsSelectable(true);error.setText("OpenCL driver/library could not load:\n"+loadError);setContentView(error);return;}LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(32,40,32,24);TextView h=new TextView(this);h.setText("Parakeet GPU test 19");h.setTextSize(25);l.addView(h);mode=new Spinner(this);mode.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"CPU","OpenCL GPU (F32 attention)"}));l.addView(mode);live=new CheckBox(this);live.setText("Streaming (supported models only)");l.addView(live);cores=new EditText(this);cores.setHint("CPU cores (blank = automatic)");cores.setInputType(2);l.addView(cores);Button p=new Button(this);p.setText("Choose Parakeet GGUF model");l.addView(p);b=new Button(this);b.setText("Hold to speak");b.setEnabled(false);l.addView(b);s=new TextView(this);s.setText("Choose a model and backend.");l.addView(s);t=new TextView(this);t.setTextSize(18);l.addView(t);Button replay=new Button(this);replay.setText("Transcribe last recording again");l.addView(replay);replay.setOnClickListener(v->{if(rec)return;replay.setEnabled(false);b.setEnabled(false);new Thread(()->{String result=nativeReplay();runOnUiThread(()->{t.setText(result);replay.setEnabled(true);b.setEnabled(true);});}).start();});p.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/octet-stream");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,7);});b.setOnTouchListener((v,e)->{if(e.getAction()==0){start();return true;}if(e.getAction()==1||e.getAction()==3){stop();return true;}return true;});ScrollView scroll=new ScrollView(this);scroll.addView(l);t.setTextIsSelectable(true);s.setTextIsSelectable(true);setContentView(scroll);}
protected void onActivityResult(int r,int c,Intent d){if(r!=7||c!=RESULT_OK)return;try{Uri u=d.getData();File f=new File(getFilesDir(),"model.gguf");InputStream i=getContentResolver().openInputStream(u);OutputStream o=new FileOutputStream(f);byte[]z=new byte[65536];int n;while((n=i.read(z))>0)o.write(z,0,n);i.close();o.close();s.setText("Loading "+mode.getSelectedItem()+"…");int be=mode.getSelectedItemPosition(),th=0;try{th=Integer.parseInt(cores.getText().toString());}catch(Exception ignored){}final int ft=th;new Thread(()->{String e=nativeLoadModelOptions(f.getAbsolutePath(),be,ft);runOnUiThread(()->{s.setText(e==null?"Model loaded. Hold to speak.":e);b.setEnabled(e==null);});}).start();}catch(Exception e){s.setText(e.toString());}}
void start(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},8);return;}String e=nativeBegin(live.isChecked());if(e!=null){s.setText(e);return;}rec=true;b.setText("Listening… release to transcribe");th=new Thread(()->{int m=AudioRecord.getMinBufferSize(16000,16,2);AudioRecord a=new AudioRecord(1,16000,16,2,Math.max(m,4096)*2);short[]q=new short[2048];float[]f=new float[2048];a.startRecording();while(rec){int n=a.read(q,0,q.length);if(n>0){for(int j=0;j<n;j++)f[j]=q[j]/32768f;String er=nativeFeed(Arrays.copyOf(f,n));if(er!=null){rec=false;runOnUiThread(()->s.setText(er));break;}if(live.isChecked()){String partial=nativeText();runOnUiThread(()->t.setText(partial));}}}a.stop();a.release();});th.start();}
void stop(){if(!rec)return;rec=false;b.setText("Hold to speak");new Thread(()->{try{th.join();}catch(Exception e){}String x=nativeFinish();runOnUiThread(()->{t.setText(x==null?"":x);s.setText("Ready");});}).start();}protected void onDestroy(){rec=false;if(loadError==null)nativeClose();super.onDestroy();}}
